export enum Genre {
  FICTION = 'FICTION',
  ESSAY = 'ESSAY',
  POETRY = 'POETRY',
  SCIENCE = 'SCIENCE',
}

@Unique('uq_Author_email', ['email'])
@Entity({ name: 'Author' })
export class Author {
  @PrimaryGeneratedColumn({ name: 'id', type: 'number' })
  id!: string

  @Column({ name: 'name', type: 'varchar2', length: 120 })
  name!: string

  @Column({ name: 'email', type: 'varchar2', length: 255 })
  email!: string

  @OneToMany(() => Book, (other) => other.author)
  books!: Book[]
}

@Check('ck_Book_genre', 'genre IN (\'FICTION\', \'ESSAY\', \'POETRY\', \'SCIENCE\')')
@Unique('uq_Book_isbn', ['isbn'])
@Index('ix_Book_author_id', ['authorId'])
@Entity({ name: 'Book' })
export class Book {
  @PrimaryGeneratedColumn({ name: 'id', type: 'number' })
  id!: string

  @Column({ name: 'isbn', type: 'varchar2', length: 13 })
  isbn!: string

  @Column({ name: 'title', type: 'clob' })
  title!: string

  @Column({ name: 'price', type: 'number', precision: 8, scale: 2 })
  price!: string

  @Column({ name: 'published_on', type: 'date' })
  publishedOn!: Date

  @Column({ name: 'genre', type: 'varchar2', length: 20 })
  genre!: Genre

  @Column({ name: 'author_id', type: 'number', precision: 19 })
  authorId!: string

  @Column({ name: 'shelf_room', type: 'clob' })
  shelfRoom!: string

  @Column({ name: 'shelf_row', type: 'number', precision: 10, nullable: true })
  shelfRow!: number | null

  @ManyToOne(() => Author, (other) => other.books, { nullable: false })
  @JoinColumn({ name: 'author_id', referencedColumnName: 'id' })
  author!: Author

  @ManyToMany(() => Tag)
  @JoinTable({ name: 'Book_Tag', joinColumn: { name: 'book_id', referencedColumnName: 'id' }, inverseJoinColumn: { name: 'tag_code', referencedColumnName: 'code' } })
  tags!: Tag[]
}

@Entity({ name: 'Tag' })
export class Tag {
  @PrimaryColumn({ name: 'code', type: 'varchar2', length: 255 })
  code!: string

  @Column({ name: 'label', type: 'clob' })
  label!: string
}

