  id: bigint('id', { mode: 'number' }).generatedByDefaultAsIdentity().primaryKey(),
  isbn: varchar('isbn', { length: 13 }).notNull(),
  title: text('title').notNull(),
  price: numeric('price', { precision: 8, scale: 2 }).notNull(),
  publishedOn: date('published_on').notNull(),
  genre: varchar('genre', { length: 20 }).notNull(),
  authorId: bigint('author_id', { mode: 'number' }).notNull().references((): AnyPgColumn => author.id),
  shelfRoom: text('shelf_room').notNull(),
  shelfRow: integer('shelf_row'),
}, (table) => [
  unique('uq_Book_isbn').on(table.isbn),
  index('ix_Book_author_id').on(table.authorId),
  check('ck_Book_genre', sql`${table.genre} IN ('FICTION', 'ESSAY', 'POETRY', 'SCIENCE')`),
])

export const tag = pgTable('Tag', {
  code: text('code').primaryKey(),
  label: text('label').notNull(),
})

export const bookTag = pgTable('Book_Tag', {
  bookId: bigint('book_id', { mode: 'number' }).notNull().references((): AnyPgColumn => book.id, { onDelete: 'cascade' }),
  tagCode: text('tag_code').notNull().references((): AnyPgColumn => tag.code, { onDelete: 'cascade' }),
}, (table) => [
  primaryKey({ name: 'pk_Book_Tag', columns: [table.bookId, table.tagCode] }),
])

