  author: one(author, { fields: [book.authorId], references: [author.id], relationName: 'Book_author' }),
  tags: many(bookTag, { relationName: 'Book_Tag_book' }),
}))

export const tagRelations = relations(tag, ({ one, many }) => ({
  bookTagLinks: many(bookTag, { relationName: 'Book_Tag_tag' }),
}))

